const PUSH = 0.1;
export function bounceBall(ball, brick) {
  const r = ball.r;
  const x0 = brick.x, x1 = brick.x + brick.w;
  const y0 = brick.y, y1 = brick.y + brick.h;

  const outLeft = (ball.x + r) - x0;      // to clear the left face, move left
  const outRight = x1 - (ball.x - r);     // to clear the right face
  const outUp = (ball.y + r) - y0;        // to clear the top face, move up
  const outDown = y1 - (ball.y - r);      // to clear the bottom face

  const penX = Math.min(outLeft, outRight);
  const penY = Math.min(outUp, outDown);

  const EPS = 1e-3;
  if (Math.abs(penX - penY) < EPS) {
    // corner
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = outLeft < outRight ? x0 - r - PUSH : x1 + r + PUSH;
    ball.y = outUp < outDown ? y0 - r - PUSH : y1 + r + PUSH;
  } else if (penX < penY) {
    ball.vx = -ball.vx;
    ball.x = outLeft < outRight ? x0 - r - PUSH : x1 + r + PUSH;
  } else {
    ball.vy = -ball.vy;
    ball.y = outUp < outDown ? y0 - r - PUSH : y1 + r + PUSH;
  }
}
