// and applies exactly ONE bounce (plus push-out) against the earliest/
// shallowest hit. Pure: only reads/mutates state. Returns the number of bricks
// destroyed.
export function resolveBricks(state) {
  const ball = state.ball;
  const overlap = [];
  const tunnel = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) {
      overlap.push(brick);
    } else {
      const hit = tunnelHit(ball, brick);
      if (hit) tunnel.push({ brick, hit });
    }
  }
  const destroyed = overlap.length + tunnel.length;

  for (const brick of overlap) { brick.alive = false; state.combo += 1; state.score += scoreForBrick(brick, state.combo); }
  for (const { brick } of tunnel) { brick.alive = false; state.combo += 1; state.score += scoreForBrick(brick, state.combo); }

  if (overlap.length) {
    const best = overlap.reduce((a, b) =>
      penetrationOf(ball, b) < penetrationOf(ball, a) ? b : a
    );
    bounceBall(ball, best);
