// Continuous (swept) test: does the segment between the ball's previous and
// current center cross the (radius-expanded) brick? Handles tunnelling where
// the discrete test would miss a fast brick. Returns { t, face } on impact.
export function tunnelHit(ball, brick) {
  const r = ball.r;
  const px = Number.isFinite(ball.prevX) ? ball.prevX : ball.x;
  const py = Number.isFinite(ball.prevY) ? ball.prevY : ball.y;
  const dx = ball.x - px, dy = ball.y - py;
  const x0 = brick.x - r, x1 = brick.x + brick.w + r;
  const y0 = brick.y - r, y1 = brick.y + brick.h + r;

  let t0 = 0, t1 = 1;
  let enterX = null, enterY = null;

  if (Math.abs(dx) < 1e-12) {
    if (px <= x0 || px >= x1) return null;
  } else {
    const a = (x0 - px) / dx, b = (x1 - px) / dx;
    enterX = Math.min(a, b);
    const exitX = Math.max(a, b);
    t0 = Math.max(t0, enterX);
    t1 = Math.min(t1, exitX);
  }
  if (Math.abs(dy) < 1e-12) {
    if (py <= y0 || py >= y1) return null;
  } else {
    const a = (y0 - py) / dy, b = (y1 - py) / dy;
    enterY = Math.min(a, b);
    const exitY = Math.max(a, b);
    t0 = Math.max(t0, enterY);
    t1 = Math.min(t1, exitY);
  }

  if (t0 > t1 + 1e-9 || t0 > 1) return null;

  // Which face limits the entry? The later-satisfied plane is the one struck.
  const EPS = 1e-3;
  let face;
  if (enterX === null) face = 'y';
  else if (enterY === null) face = 'x';
  else if (Math.abs(enterX - enterY) < EPS) face = 'corner';
  else face = enterX > enterY ? 'x' : 'y';

  return { t: t0, face };
}
```

