test('resolveBricks: seam of two bricks bounces exactly once (no cancellation)', () => {
  // The 14 px ball straddling the 8 px gap overlaps both bricks in one pass.
  // A naive per-brick bounce would flip vx on the first brick, then flip it
  // back on the second (`vx = -vx` twice cancels), letting the ball through.
  // Resolving once must leave exactly ONE horizontal flip.
  const bricks = [
    { x: 200, y: 100, w: 72, h: 20, alive: true, row: 0, points: 50 },
    { x: 280, y: 100, w: 72, h: 20, alive: true, row: 0, points: 50 },
  ];
  const state = {
    ball: ballAt(276, 108, 50, -250), // driven sideways into the seam
    bricks,
    combo: 0,
    score: 0,
  };
  const bounced = resolveBricks(state);
  assert.equal(bounced, 2, 'both overlapping seam bricks destroyed');
  assert.ok(bricks.every((b) => !b.alive));
  assert.equal(state.ball.vx, -50, 'vx flipped exactly once, not cancelled');
  assert.equal(state.ball.vy, -250, 'vy untouched on this side hit');
  assert.equal(state.combo, 2);
});

